import{_ as t,o as a,c as i,ao as s}from"./chunks/framework.ucUddl5u.js";const g=JSON.parse('{"title":"Line Protocol","description":"","frontmatter":{},"headers":[],"relativePath":"design/protocol.md","filePath":"design/protocol.md","lastUpdated":null}'),o={name:"design/protocol.md"};function r(d,e,n,l,h,c){return a(),i("div",null,[...e[0]||(e[0]=[s('<h1 id="Line-Protocol" tabindex="-1">Line Protocol <a class="header-anchor" href="#Line-Protocol" aria-label="Permalink to &quot;Line Protocol {#Line-Protocol}&quot;">​</a></h1><p>Ship of Tools is three processes that talk over sockets and stdio: the frontend, the backend daemon, and the Julia kernel (plus a supervised REPL). Every seam between them carries the same wire format — newline-delimited JSON for control, length-prefixed binary frames for payloads. The format is deliberately hand-debuggable: you can <code>tail -f</code> any seam and read what is happening.</p><p>This page describes the <em>application</em> protocol. The separate session-to-session messaging used by Claude instances (sot-comm) is a different transport entirely — see <a href="./../ref/comm">The comm protocol</a>. For where these bytes flow (Unix sockets, SSH forwarding, reconnect) see <a href="./backend">Backend &amp; Sessions</a>.</p><h2 id="Control-frames-—-NDJSON" tabindex="-1">Control frames — NDJSON <a class="header-anchor" href="#Control-frames-—-NDJSON" aria-label="Permalink to &quot;Control frames — NDJSON {#Control-frames-—-NDJSON}&quot;">​</a></h2><p>Each control message is one UTF-8 JSON object terminated by <code>\\n</code>. The envelope is fixed; the variable part is <code>op</code> plus its <code>payload</code>:</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;v&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;id&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">42</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;kind&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;req&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;op&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;mode.preview&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;payload&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:{}}</span></span></code></pre></div><table tabindex="0"><thead><tr><th style="text-align:right;">Field</th><th style="text-align:right;">Meaning</th></tr></thead><tbody><tr><td style="text-align:right;"><code>v</code></td><td style="text-align:right;">protocol version; a format bump is a one-line change</td></tr><tr><td style="text-align:right;"><code>id</code></td><td style="text-align:right;">client-chosen <code>u64</code>; responses echo it, events use <code>0</code></td></tr><tr><td style="text-align:right;"><code>kind</code></td><td style="text-align:right;"><code>&quot;req&quot;</code> request, <code>&quot;res&quot;</code> response, <code>&quot;evt&quot;</code> event</td></tr><tr><td style="text-align:right;"><code>op</code></td><td style="text-align:right;">the verb (see the op table)</td></tr><tr><td style="text-align:right;"><code>payload</code></td><td style="text-align:right;">op-specific object; may declare a binary blob</td></tr></tbody></table><p>Requests carry a client-chosen <code>id</code>; the matching response echoes that <code>id</code>. Events are unsolicited (file changed, a REPL frame arrived) and use <code>id:0</code>.</p><p>Shared Rust types live in <code>rust/protocol/</code> and are consumed by both the frontend and the backend via <code>serde</code> (tagged on <code>op</code>). The kernel side uses <code>JSON3.jl</code>. Because the envelope is versioned, an old client and a new backend can negotiate on <code>v</code>.</p><h3 id="Binary-blobs" tabindex="-1">Binary blobs <a class="header-anchor" href="#Binary-blobs" aria-label="Permalink to &quot;Binary blobs {#Binary-blobs}&quot;">​</a></h3><p>Control frames stay small and printable; bytes ride alongside them. A payload that carries binary content declares it inline:</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;blob&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:{</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;len&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">18324</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;mime&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;image/png&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}}</span></span></code></pre></div><p>The next <code>len</code> bytes on the stream <em>are</em> the blob; after them the stream resumes with the next JSON line. This avoids base64 — roughly a third of bandwidth and CPU on every PNG — while keeping the control channel greppable.</p><h3 id="Phase-1-ops" tabindex="-1">Phase 1 ops <a class="header-anchor" href="#Phase-1-ops" aria-label="Permalink to &quot;Phase 1 ops {#Phase-1-ops}&quot;">​</a></h3><p>The verbs the protocol defines in phase 1 (several later gained an additive <code>workspace_id</code> field):</p><table tabindex="0"><thead><tr><th style="text-align:right;">Op</th><th style="text-align:right;">Direction</th><th style="text-align:right;">Purpose</th></tr></thead><tbody><tr><td style="text-align:right;"><code>mode.list</code></td><td style="text-align:right;">req/res</td><td style="text-align:right;">enumerate available modes</td></tr><tr><td style="text-align:right;"><code>mode.tree.root</code></td><td style="text-align:right;">req/res</td><td style="text-align:right;">root node of a mode&#39;s tree</td></tr><tr><td style="text-align:right;"><code>mode.tree.children</code></td><td style="text-align:right;">req/res</td><td style="text-align:right;">children of a tree node</td></tr><tr><td style="text-align:right;"><code>mode.preview</code></td><td style="text-align:right;">req/res</td><td style="text-align:right;">rendered preview for a node (may blob)</td></tr><tr><td style="text-align:right;"><code>repl.eval</code></td><td style="text-align:right;">req/res</td><td style="text-align:right;">evaluate source in the REPL</td></tr><tr><td style="text-align:right;"><code>repl.interrupt</code></td><td style="text-align:right;">req</td><td style="text-align:right;">interrupt a running eval</td></tr><tr><td style="text-align:right;"><code>fs.read</code> / <code>fs.write</code></td><td style="text-align:right;">req/res</td><td style="text-align:right;">read/write a file</td></tr><tr><td style="text-align:right;"><code>concept.read</code> / <code>concept.write</code></td><td style="text-align:right;">req/res</td><td style="text-align:right;">read/write a <code>.concept/</code> annotation</td></tr><tr><td style="text-align:right;"><code>chat.send</code> / <code>chat.cancel</code></td><td style="text-align:right;">req</td><td style="text-align:right;">drive the orchestrator session</td></tr></tbody></table><p>Events: <code>tree.invalidate</code>, <code>repl.frame</code>, <code>chat.delta</code>, <code>file.changed</code>.</p><h2 id="REPL-streaming-frames" tabindex="-1">REPL streaming frames <a class="header-anchor" href="#REPL-streaming-frames" aria-label="Permalink to &quot;REPL streaming frames {#REPL-streaming-frames}&quot;">​</a></h2><p>The REPL produces multi-modal output — stdout, stderr, return values with one or more MIME representations, images (CairoMakie figures), and structured errors. The REPL shim in <code>julia/repl/src/ShipToolsRepl.jl</code> emits <strong>newline-delimited JSON frames</strong>; the backend wraps each into a <code>repl.frame</code> event on the main stream.</p><p>The shape borrows IJulia&#39;s <code>display_data</code>, flattened: no separate metadata channel, every field at the top level of the frame.</p><table tabindex="0"><thead><tr><th style="text-align:right;">Frame</th><th style="text-align:right;">Fields</th></tr></thead><tbody><tr><td style="text-align:right;"><code>stdout</code></td><td style="text-align:right;"><code>{text}</code></td></tr><tr><td style="text-align:right;"><code>stderr</code></td><td style="text-align:right;"><code>{text}</code></td></tr><tr><td style="text-align:right;"><code>value</code></td><td style="text-align:right;"><code>{mime, text}</code> for textual MIMEs; <code>{mime:&quot;image/png&quot;, blob}</code> for binary</td></tr><tr><td style="text-align:right;"><code>image</code></td><td style="text-align:right;"><code>{mime:&quot;image/png&quot;, blob}</code> — convenience for CairoMakie etc.</td></tr><tr><td style="text-align:right;"><code>error</code></td><td style="text-align:right;"><code>{message, stacktrace:[{file, line, fn}, …]}</code></td></tr><tr><td style="text-align:right;"><code>done</code></td><td style="text-align:right;"><code>{eval_id, elapsed_ms}</code></td></tr></tbody></table><p>Two properties fall out of this design:</p><ul><li><p><strong>Ordering is preserved</strong> because the REPL process has a single stdout writer; frames arrive in the order they were produced.</p></li><li><p><strong><code>done</code> is the completion signal.</strong> The backend correlates it by <code>eval_id</code> to clear the UI spinner for that evaluation. CairoMakie figures route through <code>show(io, &quot;image/png&quot;, x)</code> automatically, so plots arrive as <code>image</code> frames and render inline through the <a href="./rendering">preview layer</a> — never through a terminal graphics protocol.</p></li></ul><p>The <code>mime</code> field keeps the frame schema open: adding HTML, LaTeX, or a custom representation is a frontend-side render change, not a protocol change. Errors are structured rather than dumped to stderr, so the frontend can render stacktraces with <code>file:line</code> links.</p><h2 id="Why-NDJSON" tabindex="-1">Why NDJSON <a class="header-anchor" href="#Why-NDJSON" aria-label="Permalink to &quot;Why NDJSON {#Why-NDJSON}&quot;">​</a></h2><ul><li><p><strong>Debuggable by hand.</strong> Any seam is readable with <code>tail -f</code>; this pays for itself the first time something hangs.</p></li><li><p><strong>Cross-platform and low-ceremony.</strong> One object per line, UTF-8, works identically on Windows and Linux.</p></li><li><p><strong>Versioned.</strong> The <code>v</code> field makes a format change explicit and one-line.</p></li><li><p><strong>Cheap where it matters.</strong> Length-prefixed blobs keep binary payloads off the JSON path; parse overhead on the control channel is negligible at human-interactive rates.</p></li></ul>',26)])])}const y=t(o,[["render",r]]);export{g as __pageData,y as default};
